# Helper function to detect if we're completing an option's value.
# Uses: $cur, $prev, $words, $cword (from _init_completion)
# Sets: $opt (the option name), $val (partial value), $completing_value (0 or 1)
_nvme_detect_value_completion() {
	completing_value=0
	opt=""
	val=""

	if [[ $cur == --*=* ]]; then
		opt="${cur%%=*}"
		val="${cur#*=}"
		completing_value=1
	elif [[ $cur == "=" ]] && [[ $prev == --* ]]; then
		opt="$prev"
		completing_value=1
	elif [[ $cur != -* ]] && [[ $cur != "" ]] && [[ $prev == "=" ]] && [[ ${words[$cword-2]} == --* ]]; then
		opt="${words[$cword-2]}"
		val="$cur"
		completing_value=1
	elif [[ $cur != -* ]] && [[ $cur != "" ]] && [[ $prev == --* ]]; then
		opt="$prev"
		val="$cur"
		completing_value=1
	elif [[ $cur == "" ]] && [[ $prev == --* ]]; then
		opt="$prev"
		completing_value=1
	elif [[ $cur == "" ]] && [[ $prev == "=" ]]; then
		opt="${words[$cword-2]}"
		completing_value=1
	elif [[ $cur == "" ]] && [[ $prev == -? ]]; then
		opt="$prev"
		completing_value=1
	elif [[ $cur != -* ]] && [[ $cur != "" ]] && [[ $prev == -? ]]; then
		opt="$prev"
		val="$cur"
		completing_value=1
	fi

	# When the option word was captured unsplit (e.g. '--output-format='), drop
	# the trailing '=' so $opt matches the '--name|-s)' clauses below.
	opt="${opt%=}"
}

