			valopts+=" --sel -S"
			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--sel|-S)
						vals+=" 0 1 2 3"
						;;
				esac
			fi
			;;
		"get-error-injection")
			opts+=" --sel= -s --no-uuid -n --all-ns -a"
			valopts+=" --sel -s"
			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--sel|-s)
						vals+=" 0 1 2 3"
						;;
				esac
			fi
			;;
		"set-error-injection")
			opts+=" --data= -d --number= -n --no-uuid -N --all-ns -a --type= -t --nrtdp= -r"
			valopts+=" --data -d --number -n --type -t --nrtdp -r"
			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--data|-d)
						wantfiles=1
						;;
				esac
			fi
			;;
		"get-enable-ieee1667-silo")
			opts+=" --sel= -s --no-uuid -n"
			valopts+=" --sel -s"
			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--sel|-s)
						vals+=" 0 1 2 3"
						;;
				esac
			fi
			;;
		"set-enable-ieee1667-silo")
			opts+=" --enable -e --save -s --no-uuid -n"
			;;
		"hardware-component-log")
			opts+=" --comp-id= -i --list -l"
			valopts+=" --comp-id -i"
			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--comp-id|-i)
						vals+=" asic nand dram pmic pcb cap reg case sn country hw-rev born-on-date vendor"
						;;
				esac
			fi
			;;
		"get-latency-monitor")
			opts+=" --sel= -s --namespace-id= -n --no-uuid -u"
			valopts+=" --sel -s --namespace-id -n"
			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--sel|-s)
						vals+=" 0 1 2 3"
						;;
				esac
			fi
			;;
		"get-clear-pcie-correctable-errors")
			opts+=" --sel= -s --namespace-id= -n --no-uuid -u"
			valopts+=" --sel -s --namespace-id -n"
			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--sel|-s)
						vals+=" 0 1 2 3"
						;;
				esac
			fi
			;;
		"get-telemetry-profile")
			opts+=" --sel= -s --namespace-id= -n --no-uuid -u"
			valopts+=" --sel -s --namespace-id -n"
			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--sel|-s)
						vals+=" 0 1 2 3"
						;;
				esac
			fi
			;;
		"persistent-event-log")
			opts+=" --action= -a --log_len= -l --raw-binary -b"
			valopts+=" --action -a --log_len -l"
			;;
		"get-idle-wakeup-time")
			opts+=" --sel= -s --namespace-id= -n --no-uuid -u"
			valopts+=" --sel -s --namespace-id -n"
			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--sel|-s)
						vals+=" 0 1 2 3"
						;;
				esac
			fi
			;;
	esac

	opts+=" -h --help"

	# If we thought we were completing a value but $opt is not a value-taking
	# option, it is a flag -- fall back to normal option completion.
	if [[ $completing_value -eq 1 ]] && [[ " $valopts " != *" $opt "* ]]; then
		completing_value=0
	fi

	if [[ $completing_value -eq 1 ]]; then
		if [[ $vals != " " ]]; then
			COMPREPLY+=( $( compgen -W "$vals" -- "$val" ) )
		elif [[ $wantfiles -eq 1 ]]; then
			: # value is a filename; let 'complete -o default' offer files
		else
			# No candidate values (e.g. a NUM or free-form string); offer
			# nothing and suppress the filename fallback.
			compopt +o default
		fi
	else
		COMPREPLY+=( $( compgen -W "$opts" -- "$cur" ) )
		# Suppress the trailing space only when the sole completion ends in '=',
		# so the user can type the value immediately. With more than one candidate
		# bash appends nothing, so nospace must not fire.
		[[ ${#COMPREPLY[@]} -eq 1 && ${COMPREPLY[0]} == *= ]] && compopt -o nospace
	fi

	return 0
}

plugin_sed_opts () {
	local opts=""
	local valopts=""
	local vals=""
	local opt=""
	local val=""

	local nonopt_args=0
	local has_device=0
	local i
	for (( i=0; i < ${#words[@]}-1; i++ )); do
		if [[ ${words[i]} != -* ]] && [[ ${words[i]} != "=" ]]; then
			(( nonopt_args += 1 ))
			if [[ ${words[i]} == /dev/nvme* ]]; then
				has_device=1
			fi
		fi
	done

	if [[ $nonopt_args -ge 3 ]] && [[ $has_device -eq 0 ]] && \
	   [[ "$1" != "help" ]] && [[ "$1" != "version" ]]; then
		opts="/dev/nvme* "
	fi

	opts+=" "
	vals+=" "

	local completing_value=0
	local wantfiles=0
	_nvme_detect_value_completion
	case "$1" in
		"discover"|"1")
			opts+=" --verbose -V --udev -u"
			;;
		"initialize")
			opts+=" --read-only -r"
			;;
		"revert")
			opts+=" --destructive -e --psid -p"
			;;
		"lock")
			opts+=" --read-only -r --ask-key -k"
			;;
		"unlock")
			opts+=" --read-only -r --ask-key -k"
			;;
	esac

	opts+=" -h --help"

	# If we thought we were completing a value but $opt is not a value-taking
	# option, it is a flag -- fall back to normal option completion.
	if [[ $completing_value -eq 1 ]] && [[ " $valopts " != *" $opt "* ]]; then
		completing_value=0
	fi

	if [[ $completing_value -eq 1 ]]; then
		if [[ $vals != " " ]]; then
			COMPREPLY+=( $( compgen -W "$vals" -- "$val" ) )
		elif [[ $wantfiles -eq 1 ]]; then
			: # value is a filename; let 'complete -o default' offer files
		else
			# No candidate values (e.g. a NUM or free-form string); offer
			# nothing and suppress the filename fallback.
			compopt +o default
		fi
	else
		COMPREPLY+=( $( compgen -W "$opts" -- "$cur" ) )
		# Suppress the trailing space only when the sole completion ends in '=',
		# so the user can type the value immediately. With more than one candidate
		# bash appends nothing, so nospace must not fire.
		[[ ${#COMPREPLY[@]} -eq 1 && ${COMPREPLY[0]} == *= ]] && compopt -o nospace
	fi

	return 0
}

plugin_solidigm_opts () {
	local opts=""
	local valopts=""
	local vals=""
	local opt=""
	local val=""

	local nonopt_args=0
	local has_device=0
	local i
	for (( i=0; i < ${#words[@]}-1; i++ )); do
		if [[ ${words[i]} != -* ]] && [[ ${words[i]} != "=" ]]; then
			(( nonopt_args += 1 ))
			if [[ ${words[i]} == /dev/nvme* ]]; then
				has_device=1
			fi
		fi
	done

	if [[ $nonopt_args -ge 3 ]] && [[ $has_device -eq 0 ]] && \
	   [[ "$1" != "help" ]] && [[ "$1" != "version" ]]; then
		opts="/dev/nvme* "
	fi

	opts+=" "
	vals+=" "

	local completing_value=0
	local wantfiles=0
	_nvme_detect_value_completion
	case "$1" in
		"version"|"help")
			;;
		*)
