			if [[ $completing_value -eq 1 ]]; then
				case $opt in
					--config-file|-j)
						wantfiles=1
						;;
					--source-file|-s)
						wantfiles=1
						;;
				esac
			fi
			;;
		"clear-pcie-correctable-errors")
