			valopts+=" --uuid-index -U --sample-time -s --type -t --run-time -r --flush-freq -f --trigger-field -T --trigger-threshold -V"
			;;
	esac

	opts+=" -h --help"

	# If we thought we were completing a value but $opt is not a value-taking
