		innogrit inspur intel mangoboost memblaze micron netapp nvidia sndk
		sfx seagate shannon ssstc toshiba transcend utils virtium wdc ymtc zns
		nbft keys exclusion registry config feat lm ocp sed solidigm
	)

	local func subcmd
	if [[ ${#words[*]} -lt 3 ]]; then
		COMPREPLY+=( $(compgen -W "${_cmds[*]}" -- "$cur" ) )
	else
		for subcmd in "${!_plugin_subcmds[@]}"; do
			if [[ ${words[1]} == "$subcmd" ]]; then
				if [[ ${#words[*]} -lt 4 ]]; then
					COMPREPLY+=( $(compgen -W "${_plugin_subcmds[$subcmd]}" -- "$cur" ) )
				else
					func=${_plugin_funcs[$subcmd]}
					$func "${words[2]}" "$prev"
				fi
				return 0
			fi
		done

		nvme_list_opts "${words[1]}" "$prev"
	fi

	return 0
}

